// This file implements organization-scoped policy publishing, rollback,
// and review on top of the decision core. Each organization versions its
// own policy set independently; all state is in-memory and lives until
// the service instance ends.
package darksafe

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// Effect is the outcome a policy produces when it matches a request.
type Effect string

const (
	EffectAllow Effect = "allow"
	EffectDeny  Effect = "deny"
)

// Policy binds one subject and one action to a scope with an effect.
type Policy struct {
	ID        string
	Subject   string
	Action    string
	Scope     string
	Effect    Effect
	Recursive bool // false: only the exact scope; true: the scope and its descendants
	// ResourceID optionally narrows the policy to one exact resource. Empty
	// keeps the legacy scope-only matching. A non-empty value adds a
	// condition on top of subject, action, scope and the organization
	// checks: it never replaces them. Comparison is against the request's
	// raw resource ID, byte for byte: case sensitive, spaces significant,
	// no wildcard or scope-path interpretation, and the resource needs no
	// prior registration.
	//
	// The omitempty tag is load bearing for audit fingerprints: the legacy
	// JSON fingerprint family never had this field, and an empty value must
	// keep serializing to exactly the old bytes.
	ResourceID string `json:",omitempty"`
}

// Sentinel errors so callers can distinguish failure causes with errors.Is.
var (
	// ErrVersionConflict means the caller's expected current version is stale.
	ErrVersionConflict = errors.New("darksafe: version conflict")
	// ErrVersionNotFound means the requested historical version does not exist.
	ErrVersionNotFound = errors.New("darksafe: version not found")
	// ErrInvalidPolicySet means the submitted policy set failed validation.
	ErrInvalidPolicySet = errors.New("darksafe: invalid policy set")
	// ErrMissingOrganization means an operation was called without an organization.
	ErrMissingOrganization = errors.New("darksafe: organization is required")
)

// OrgRequest is an access request evaluated against one organization's
// published policies. Both organizations must equal the decision organization.
type OrgRequest struct {
	SubjectOrg  string
	ResourceOrg string
	Subject     Subject
	Resource    Resource
	Action      string
}

// Store holds every organization's published policy versions. It is safe
// for concurrent use and keeps all state in memory.
type Store struct {
	mu   sync.Mutex
	orgs map[string]*orgState
}

type orgState struct {
	current  int              // 0 means nothing published yet
	versions map[int][]Policy // immutable snapshots per version
	audit    []*AuditRecord   // gapless, append-only audit chain
}

// NewStore returns an empty Store.
func NewStore() *Store {
	return &Store{orgs: make(map[string]*orgState)}
}

func (s *Store) orgLocked(name string) *orgState {
	st, ok := s.orgs[name]
	if !ok {
		st = &orgState{versions: make(map[int][]Policy)}
		s.orgs[name] = st
	}
	return st
}

// CurrentVersion reports the organization's current version, 0 if it has
// never published.
func (s *Store) CurrentVersion(org string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	if st, ok := s.orgs[org]; ok {
		return st.current
	}
	return 0
}

// Publish validates and publishes a complete policy set as the next
// version. expectedVersion must equal the organization's current version;
// on any validation or version failure nothing changes and no version
// number is consumed.
func (s *Store) Publish(org string, expectedVersion int, policies []Policy) (int, error) {
	if org == "" {
		return 0, ErrMissingOrganization
	}
	snapshot, err := validatePolicies(policies)
	if err != nil {
		return 0, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	if expectedVersion != st.current {
		return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
	}
	return st.commitVersionLocked(org, snapshot, 0, false), nil
}

// Rollback republishes the full content of an existing historical version
// as a new version. History is never deleted or rewritten.
func (s *Store) Rollback(org string, expectedVersion, targetVersion int) (int, error) {
	if org == "" {
		return 0, ErrMissingOrganization
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	src, ok := st.versions[targetVersion]
	if !ok {
		return 0, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, targetVersion)
	}
	if expectedVersion != st.current {
		return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
	}
	snapshot := append([]Policy(nil), src...)
	return st.commitVersionLocked(org, snapshot, targetVersion, true), nil
}

// commitVersionLocked advances the organization to the next version with
// the given policy snapshot and appends the matching policy-change record
// to the audit chain. It runs under the store mutex, so the new version
// and its audit record become visible together; callers must have already
// validated the input and checked the expected version, so a failed
// operation never reaches this point and leaves no record. A rollback
// passes its source version and rolledBack=true; an ordinary publish
// passes 0 and false.
func (st *orgState) commitVersionLocked(org string, snapshot []Policy, sourceVersion int, rolledBack bool) int {
	st.current++
	st.versions[st.current] = snapshot
	st.appendAuditLocked(org, AuditPolicyChange, &PolicyChange{
		Version:       st.current,
		Policies:      snapshot,
		SourceVersion: sourceVersion,
		RolledBack:    rolledBack,
	}, nil)
	return st.current
}

// Policies returns a copy of the full policy set of one version. Mutating
// the result does not affect published content.
func (s *Store) Policies(org string, version int) ([]Policy, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	st, ok := s.orgs[org]
	if !ok {
		return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
	}
	src, ok := st.versions[version]
	if !ok {
		return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
	}
	return append([]Policy(nil), src...), nil
}

// Decide evaluates a request against the organization's current version.
// The whole decision uses that single version's snapshot, and the version
// actually used is reported in Decision.Version.
//
// Every call with a non-empty decision organization leaves a decision
// record, including envelope rejections (disabled subject, missing fields,
// organization mismatch) and the no-published-version denial. A call with
// an empty organization rejects as before and creates no record, because
// there is no organization to attribute it to. The evaluation and record
// append are atomic: a concurrent publish can never make the recorded
// version differ from the version that was evaluated.
func (s *Store) Decide(org string, req OrgRequest) Decision {
	if org == "" {
		d, _ := checkRequest(org, req)
		return d
	}
	if d, ok := checkRequest(org, req); !ok {
		s.mu.Lock()
		st := s.orgLocked(org)
		st.appendAuditLocked(org, AuditDecision, nil, &DecisionRecord{Request: req, Decision: d})
		s.mu.Unlock()
		return d
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	version := st.current
	var d Decision
	if version == 0 {
		d = Decision{Allowed: false, Reason: "organization has no published version"}
	} else {
		d = evaluate(req, st.versions[version], version)
	}
	st.appendAuditLocked(org, AuditDecision, nil, &DecisionRecord{Request: req, Decision: d})
	return d
}

// Review re-evaluates a request against a specific historical version.
// Later publishes or rollbacks cannot change its outcome; a version that
// does not exist is a denial with a reason, never a silent fallback to
// the current version.
func (s *Store) Review(org string, version int, req OrgRequest) Decision {
	if d, ok := checkRequest(org, req); !ok {
		return d
	}
	s.mu.Lock()
	var policies []Policy
	found := false
	if st, ok := s.orgs[org]; ok {
		if src, ok := st.versions[version]; ok {
			policies = append([]Policy(nil), src...)
			found = true
		}
	}
	s.mu.Unlock()
	if !found {
		return Decision{Allowed: false, Reason: fmt.Sprintf("version %d not found", version)}
	}
	return evaluate(req, policies, version)
}

// checkRequest validates the request envelope. Every failure is a denial
// with a distinguishable reason.
func checkRequest(org string, req OrgRequest) (Decision, bool) {
	switch {
	case org == "":
		return Decision{Allowed: false, Reason: "missing decision organization"}, false
	case req.SubjectOrg == "":
		return Decision{Allowed: false, Reason: "missing subject organization"}, false
	case req.ResourceOrg == "":
		return Decision{Allowed: false, Reason: "missing resource organization"}, false
	case req.Subject.ID == "":
		return Decision{Allowed: false, Reason: "missing subject id"}, false
	case req.Resource.ID == "":
		return Decision{Allowed: false, Reason: "missing resource id"}, false
	case req.Action == "":
		return Decision{Allowed: false, Reason: "missing action"}, false
	}
	if req.SubjectOrg != org || req.ResourceOrg != org {
		return Decision{Allowed: false, Reason: "organization mismatch"}, false
	}
	if err := validateScope(req.Resource.Scope); err != nil {
		return Decision{Allowed: false, Reason: "invalid scope: " + err.Error()}, false
	}
	if req.Subject.Disabled {
		return Decision{Allowed: false, Reason: "subject is disabled"}, false
	}
	return Decision{}, true
}

// evaluate applies one version's policies to a request. Subject roles are
// deliberately ignored: only the selected version's policies decide.
func evaluate(req OrgRequest, policies []Policy, version int) Decision {
	seen := make(map[string]struct{})
	denied := false
	allowed := false
	for _, p := range policies {
		if p.Subject != req.Subject.ID || p.Action != req.Action {
			continue
		}
		if !scopeMatches(p, req.Resource.Scope) {
			continue
		}
		// A resource restriction is an additional condition, not a
		// replacement for the scope check: even an equal ID cannot match a
		// resource outside the policy's scope (including outside a
		// recursive scope's subtree). The request envelope already
		// rejected an empty resource ID, so an empty ResourceID here means
		// "no restriction", never a match on a missing ID.
		if p.ResourceID != "" && p.ResourceID != req.Resource.ID {
			continue
		}
		seen[p.ID] = struct{}{}
		switch p.Effect {
		case EffectDeny:
			denied = true
		case EffectAllow:
			allowed = true
		}
	}
	matched := make([]string, 0, len(seen))
	for id := range seen {
		matched = append(matched, id)
	}
	sort.Strings(matched)
	switch {
	case denied:
		return Decision{Allowed: false, Reason: "matched deny policy", Matched: matched, Version: version}
	case allowed:
		return Decision{Allowed: true, Reason: "matched allow policy", Matched: matched, Version: version}
	default:
		return Decision{Allowed: false, Reason: "no matching allow policy", Matched: matched, Version: version}
	}
}

// scopeMatches reports whether a policy's scope covers the request scope.
// Matching is by slash-separated segments, so "org/a" never covers "org/ab".
func scopeMatches(p Policy, scope string) bool {
	if p.Scope == scope {
		return true
	}
	return p.Recursive && strings.HasPrefix(scope, p.Scope+"/")
}

// validatePolicies checks a submitted policy set and returns a detached
// copy, so later caller mutations cannot affect published content.
func validatePolicies(policies []Policy) ([]Policy, error) {
	seen := make(map[string]struct{}, len(policies))
	out := make([]Policy, len(policies))
	for i, p := range policies {
		if p.ID == "" {
			return nil, fmt.Errorf("%w: policy at index %d has an empty id", ErrInvalidPolicySet, i)
		}
		if _, dup := seen[p.ID]; dup {
			return nil, fmt.Errorf("%w: duplicate policy id %q", ErrInvalidPolicySet, p.ID)
		}
		seen[p.ID] = struct{}{}
		if p.Subject == "" {
			return nil, fmt.Errorf("%w: policy %q is missing a subject", ErrInvalidPolicySet, p.ID)
		}
		if p.Action == "" {
			return nil, fmt.Errorf("%w: policy %q is missing an action", ErrInvalidPolicySet, p.ID)
		}
		if p.Effect != EffectAllow && p.Effect != EffectDeny {
			return nil, fmt.Errorf("%w: policy %q has unknown effect %q", ErrInvalidPolicySet, p.ID, p.Effect)
		}
		if err := validateScope(p.Scope); err != nil {
			return nil, fmt.Errorf("%w: policy %q has invalid scope: %v", ErrInvalidPolicySet, p.ID, err)
		}
		out[i] = p
	}
	return out, nil
}

// validateScope rejects empty paths, leading/trailing slashes, consecutive
// slashes, and "." or ".." segments.
func validateScope(scope string) error {
	if scope == "" {
		return errors.New("scope is empty")
	}
	if strings.HasPrefix(scope, "/") || strings.HasSuffix(scope, "/") {
		return fmt.Errorf("scope %q has a leading or trailing slash", scope)
	}
	for _, seg := range strings.Split(scope, "/") {
		if seg == "" {
			return fmt.Errorf("scope %q contains consecutive slashes", scope)
		}
		if seg == "." || seg == ".." {
			return fmt.Errorf("scope %q contains invalid segment %q", scope, seg)
		}
	}
	return nil
}

// This file implements offline review of a single audited decision. It
// works solely from exported audit material: the complete record export,
// the separately retained checkpoint, and a target sequence. No Store is
// created or restored, so an organization can confirm why an access was
// allowed or denied long after the service instance that decided it has
// ended.
//
// The complete input must first validate as an audit chain. The policy
// version a decision actually used is recovered exclusively from policy
// change records preceding that decision within the same organization's
// export; later publishes or rollbacks, and a wider later export, cannot
// change the recomputed result.
package darksafe

import "fmt"

// OfflineDecisionReview compares the decision stored in an audited record
// with a decision recomputed purely from the exported material.
type OfflineDecisionReview struct {
	// Seq is the reviewed decision record's sequence.
	Seq int
	// Original is the decision preserved in the audited record.
	Original Decision
	// Recomputed is the decision evaluated again offline from the saved
	// request and the policy version it originally used.
	Recomputed Decision
	// Consistent reports whether both decisions agree on every field
	// (allowance, reason, matched policies and version), treating a nil
	// matched list and an empty matched list as the same.
	Consistent bool
}

// RecheckDecisionOffline re-evaluates one decision record offline. org is
// the organization name, records is its complete export starting at
// sequence 1 (a valid prefix is sufficient when paired with its own
// checkpoint), cp is the separately saved checkpoint, and seq identifies
// the decision record to review. The call is read-only: it neither mutates
// the supplied material nor appends audit records, and the returned
// decisions are detached from the input slices.
//
// The entire export is chain-validated before any result is produced;
// tampering anywhere, including in records after the target, fails the
// review. Distinguishable errors follow the other audit entry points:
// ErrMissingOrganization for an empty organization, ErrAuditNotFound for a
// non-positive or absent target sequence, and ErrAuditNotADecision when the
// target is a policy change record. When the saved decision names a
// policy version whose full content has no change record before the
// target, ErrVersionNotFound is returned; a newer version is never
// substituted, and a request the envelope would reject never masks the
// missing version.
//
// The fingerprint only proves the material matches its checkpoint; it
// cannot stand in for evaluating the request itself. So even when the
// declared version exists and carries an otherwise matching allow policy,
// the recomputation enforces the same request rules as the online
// decision: a disabled subject, an organization mismatch, a missing
// subject or resource organization or identifier, an empty action, and an
// illegal resource scope all deny, with the same reasons and precedence as
// Decide. Such a rejection uses no policies, so the recomputed decision
// reports version 0 with no matched policies; it is then compared field by
// field with the preserved original and may come back inconsistent.
func RecheckDecisionOffline(org string, records []AuditRecord, cp Checkpoint, seq int) (OfflineDecisionReview, error) {
	if org == "" {
		return OfflineDecisionReview{}, ErrMissingOrganization
	}
	// Validate the whole export first. A subject-filtered page, a fragment
	// missing the beginning, or a checkpoint that does not pin the records
	// all fail here, as does any corruption after the target.
	if err := VerifyAudit(org, records, cp); err != nil {
		return OfflineDecisionReview{}, err
	}
	if seq < 1 {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	if seq > len(records) {
		return OfflineDecisionReview{}, fmt.Errorf("%w: export ends at %d, no sequence %d", ErrAuditNotFound, len(records), seq)
	}
	rec := &records[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}

	original := cloneDecisionValue(rec.Decision.Decision)
	req := rec.Decision.Request
	// Detach the request list by non-nil rather than by length: a non-nil
	// empty role list with spare capacity must not be shared back with the
	// caller's material, even though evaluation never reads any element.
	req.Subject.Roles = cloneStrings(req.Subject.Roles)
	version := original.Version

	// The version's full content must travel in a same-organization policy
	// change record positioned before the decision. The replay core resolves
	// the version before replaying any request rule, so a request the
	// envelope rejects cannot mask a missing or later-only version.
	resolve := func(want int) versionPolicies {
		if policies, found := policiesBefore(records, seq-1, want); found {
			return versionPolicies{policies: policies}
		}
		if _, later := policiesBefore(records, len(records), want); later {
			return versionPolicies{status: replayVersionAfterTarget}
		}
		return versionPolicies{status: replayVersionAbsent}
	}
	recomputed, status := replayRecordedDecision(org, req, version, resolve)
	switch status {
	case replayVersionAfterTarget:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, whose change record appears only after it",
			ErrVersionNotFound, seq, version)
	case replayVersionAbsent:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, which has no policy change record in the export",
			ErrVersionNotFound, seq, version)
	}

	return OfflineDecisionReview{
		Seq:        seq,
		Original:   original,
		Recomputed: recomputed,
		Consistent: decisionsEqual(original, recomputed),
	}, nil
}

// policiesBefore searches records[:limit] for the policy change record that
// published version and returns a detached copy of its full content. The
// gapless chain validation guarantees records are in sequence order.
func policiesBefore(records []AuditRecord, limit, version int) ([]Policy, bool) {
	for i := 0; i < limit; i++ {
		r := &records[i]
		if r.Kind != AuditPolicyChange || r.Change == nil {
			continue
		}
		if r.Change.Version == version {
			return append([]Policy(nil), r.Change.Policies...), true
		}
	}
	return nil, false
}

// cloneDecisionValue returns a decision detached from the input's matched
// slice. The list is detached whenever it is non-nil, including a non-nil
// empty list that still has spare capacity, so an append by one receiver
// can never reach another copy.
func cloneDecisionValue(d Decision) Decision {
	d.Matched = cloneStrings(d.Matched)
	return d
}

// decisionsEqual compares every decision field. A nil matched list and an
// empty matched list describe the same set of hits.
func decisionsEqual(a, b Decision) bool {
	if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
		return false
	}
	if len(a.Matched) == 0 && len(b.Matched) == 0 {
		return true
	}
	if len(a.Matched) != len(b.Matched) {
		return false
	}
	for i := range a.Matched {
		if a.Matched[i] != b.Matched[i] {
			return false
		}
	}
	return true
}

// This file holds the shared core of single-decision review. The online
// Store.RecheckDecision and the store-free RecheckDecisionOffline acquire
// their material differently — one reads an organization's live history
// and version snapshots, the other a chain-validated export paired with its
// separately retained checkpoint — but once the recorded request and the
// version it actually used are in hand, both replay the exact same
// judgment. That judgment lives only here so the two entry points can never
// drift on version-zero handling, envelope rejection order, or how a
// historical policy set is evaluated.
package darksafe

// replayStatus reports whether replayRecordedDecision produced a decision
// or why the declared version could not be replayed.
type replayStatus int

const (
	// replayDecided means a Decision was recomputed.
	replayDecided replayStatus = iota
	// replayVersionAbsent means content for the declared version exists
	// nowhere in the reviewer's material.
	replayVersionAbsent
	// replayVersionAfterTarget means the version's content exists, but only
	// in a policy change record positioned after the reviewed decision.
	// Online material never yields this: live version snapshots carry no
	// position relative to audit records.
	replayVersionAfterTarget
)

// versionPolicies is one resolver verdict: either the detached full policy
// set of the requested version, or a status explaining why it is unusable.
type versionPolicies struct {
	policies []Policy
	status   replayStatus
}

// resolveVersionPolicies supplies the full content of a non-zero version
// named by a reviewed decision. Implementations are responsible for
// detaching the returned policies from any state or input material.
type resolveVersionPolicies func(version int) versionPolicies

// replayRecordedDecision re-judges a recorded request against the version
// the record declares it actually used. Later publishes or rollbacks are
// never substituted for that version.
//
// A version-0 record first replays the envelope rejections in their fixed
// order (missing organizations and identifiers, empty action, organization
// mismatch, illegal scope, disabled subject); a request that passes is the
// "organization has no published version" denial.
//
// For a non-zero record the version is resolved before any request rule is
// applied: a missing, or only-later, version is an error the caller turns
// into ErrVersionNotFound and must never be masked by an envelope denial,
// even for a disabled subject. Once the version is in hand, the same
// envelope checks run before policy evaluation, so a rejection reports
// version 0 with no matched policies regardless of what the version
// contains. Evaluation itself is the historical policy set only: deny
// overrides allow, matched identifiers are sorted, resource restrictions
// narrow rather than replace scope matching, and subject roles never stand
// in for an organization policy.
func replayRecordedDecision(org string, req OrgRequest, version int, resolve resolveVersionPolicies) (Decision, replayStatus) {
	if version == 0 {
		// The original evaluation used no published version: replay the
		// envelope rejections exactly, in their recorded order, then the
		// not-yet-published denial.
		if d, ok := checkRequest(org, req); !ok {
			return d, replayDecided
		}
		return Decision{Allowed: false, Reason: "organization has no published version"}, replayDecided
	}
	// Resolve the version first. A request the envelope would reject must
	// not turn a missing or later-only declared version into an ordinary
	// denial.
	resolved := resolve(version)
	if resolved.status != replayDecided {
		return Decision{}, resolved.status
	}
	// The version exists as claimed, but chain integrity does not imply the
	// request was admissible: re-run the same envelope checks the online
	// decision runs before any policy is consulted. A rejection here
	// evaluates no policies, hence version 0 and no matches, even when the
	// version holds a fully matching allow policy.
	if d, ok := checkRequest(org, req); !ok {
		return d, replayDecided
	}
	return evaluate(req, resolved.policies, version), replayDecided
}

